import{debug}from"../Debug.js";import{PuppeteerURL}from"../util.js";import{BidiSerializer}from"./Serializer.js";export const debugError=debug("puppeteer:error");export async function releaseReference(e,r){r.handle&&await e.connection.send("script.disown",{target:e.target,handles:[r.handle]}).catch((e=>{debugError(e)}))}export function createEvaluationError(e){if("error"!==e.exception.type)return BidiSerializer.deserialize(e.exception);const[r="",...t]=e.text.split(": "),n=t.join(": "),i=new Error(n);i.name=r;const o=[];if(e.stackTrace&&o.length<Error.stackTraceLimit)for(const r of e.stackTrace.callFrames.reverse()){if(PuppeteerURL.isPuppeteerURL(r.url)&&r.url!==PuppeteerURL.INTERNAL_URL){const e=PuppeteerURL.parse(r.url);o.unshift(`    at ${r.functionName||e.functionName} (${e.functionName} at ${e.siteString}, <anonymous>:${r.lineNumber}:${r.columnNumber})`)}else o.push(`    at ${r.functionName||"<anonymous>"} (${r.url}:${r.lineNumber}:${r.columnNumber})`);if(o.length>=Error.stackTraceLimit)break}return i.stack=[e.text,...o].join("\n"),i}